-- KIE reference prices (KIE credits, $0.005 each), documented on 2026-10-22. Inserting one re-prices the model under the
-- current global pricing policy (trigger policy_follow_change); customer prices are never written here.
insert into app_private.supplier_cost_versions (model_id, version, schedule, usd_per_credit, source_kind, source_url, source_checked_at, note)
select v.model_id, 1, v.schedule::jsonb, 0.005, 'documented', 'https://kie.ai/pricing', timestamptz '2026-10-22T12:00:00Z', v.note
from (values
  ('kling-3-0-turbo', $j${"unit":"second","durationOption":"duration","dims":["resolution"],"rates":{"720p":18,"1080p":22.5}}$j$, 'KIE price list: kling 3.0 turbo, text/image-to-video, 720P/1080P = 18/22.5 credits per second.'),
  ('kling-3-0-omni', $j${"unit":"second","durationOption":"duration","dims":["resolution","audio"],"rates":{"720p|off":14,"720p|on":18,"1080p|off":18,"1080p|on":23,"4k|off":67,"4k|on":67}}$j$, 'KIE price list: kling 3.0 omni, text/image/reference-to-video without video input: 720p 14/18, 1080p 18/23, 4k 67 credits per second (no audio/with audio).'),
